//! `skip_balanced` — Advance past one balanced `open`/`close` structure (an object or an array) starting at `bytes[start] == open`, skipping over any string cont

use super::skip_string;

/// Advance past one balanced `open`/`close` structure (an object or an array) starting at
/// `bytes[start] == open`, skipping over any string content (which may itself contain `open`/`close`
/// bytes) rather than counting them.
pub(crate) fn skip_balanced(bytes: &[u8], start: usize, open: u8, close: u8) -> Result<usize, String> {
    let mut depth = 0i32;
    let mut i = start;
    loop {
        match bytes.get(i) {
            None => return Err("unterminated structure in seed JSON".to_string()),
            Some(b'"') => i = skip_string(bytes, i)?,
            Some(&c) if c == open => {
                depth += 1;
                i += 1;
            }
            Some(&c) if c == close => {
                depth -= 1;
                i += 1;
                if depth == 0 {
                    return Ok(i);
                }
            }
            Some(_) => i += 1,
        }
    }
}
